+//! Process-lifetime, probe-sized stripes for stage telemetry. Writers select one
+//! bounded slot per thread; slot counters survive thread exit. Only observation
+//! aggregates slots. No sampling, I/O, authority or admission behavior changes.
+use super::{AtomicU64, Ordering, COMPONENT_COUNT, STAGE_COUNT};
+use std::{cell::Cell, sync::OnceLock};
+
+#[derive(Default)]
+struct Pair { nanos: AtomicU64, calls: AtomicU64 }
+#[repr(align(64))]
+struct Stripe { component: [[Pair; STAGE_COUNT]; COMPONENT_COUNT] }
+impl Default for Stripe {
+    fn default() -> Self { Self { component: [const { [const { Pair { nanos: AtomicU64::new(0), calls: AtomicU64::new(0) } }; STAGE_COUNT] }; COMPONENT_COUNT] } }
+}
+static STRIPES: OnceLock<Vec<OnceLock<Box<Stripe>>>> = OnceLock::new();
+static THREAD_SEQUENCE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
+thread_local! { static THREAD_SLOT: Cell<Option<usize>> = const { Cell::new(None) }; }
+
+pub(super) fn configure(budget: crate::resource_probe::DaemonResourceBudget) {
+    // Private experimental control: keep every original global counter active.
+    if std::env::var("TOFU_DB_STAGE_COUNTER_STRIPES").as_deref() == Ok("0") { return; }
+    let count=budget.snapshot.logical_cpus.unwrap_or(1).max(1)
+        .min(budget.maximum_connections.max(1));
+    STRIPES.get_or_init(|| (0..count).map(|_|OnceLock::new()).collect());
+}
+
+pub(super) fn note(component: usize, stage: usize, nanos: u64) -> bool {
+    let Some(stripes)=STRIPES.get() else { return false; };
+    let index=THREAD_SLOT.with(|slot| match slot.get() {
+        Some(index)=>index,
+        None=> { let index=THREAD_SEQUENCE.fetch_add(1,Ordering::Relaxed)%stripes.len(); slot.set(Some(index));index }
+    });
+    let stripe=stripes[index].get_or_init(||Box::new(Stripe::default()));
+    let pair=&stripe.component[component][stage];
+    pair.nanos.fetch_add(nanos,Ordering::Relaxed);
+    pair.calls.fetch_add(1,Ordering::Relaxed);
+    true
+}
+
+pub(super) fn component(component: usize, stage: usize, nanos: bool) -> u64 {
+    let mut total=0u64;
+    if let Some(stripes)=STRIPES.get() {
+        for slot in stripes { if let Some(stripe)=slot.get() {
+            let pair=&stripe.component[component][stage];
+            total=total.wrapping_add(if nanos { pair.nanos.load(Ordering::Relaxed) }
+                else { pair.calls.load(Ordering::Relaxed) });
+        } }
+    }
+    total
+}
+
+/// One contiguous pass for metrics/reporting; do not scan all slots separately
+/// for every scalar field in a full stage/component report.
+pub(super) fn snapshot() -> Vec<(u64,u64)> {
+    let mut totals=vec![(0u64,0u64);COMPONENT_COUNT*STAGE_COUNT];
+    if let Some(stripes)=STRIPES.get() {
+        for slot in stripes { if let Some(stripe)=slot.get() {
+            for (component, stages) in stripe.component.iter().enumerate() {
+                for (stage,pair) in stages.iter().enumerate() {
+                    let total=&mut totals[component*STAGE_COUNT+stage];
+                    total.0=total.0.wrapping_add(pair.nanos.load(Ordering::Relaxed));
+                    total.1=total.1.wrapping_add(pair.calls.load(Ordering::Relaxed));
+                }
+            }
+        } }
+    }
+    totals
+}
+
+#[derive(serde::Serialize)]
+#[serde(rename_all="camelCase")]
+pub(crate) struct Metrics { slots: usize, allocated_slots: usize,
+    bytes_per_slot: usize, maximum_counter_bytes: usize, allocated_counter_bytes: usize }
+pub(super) fn metrics() -> Metrics {
+    let slots=STRIPES.get().map_or(0,Vec::len);
+    let allocated_slots=STRIPES.get().map_or(0,|stripes|stripes.iter().filter(|s|s.get().is_some()).count());
+    let bytes_per_slot=std::mem::size_of::<Stripe>();
+    Metrics { slots,allocated_slots,bytes_per_slot,maximum_counter_bytes:slots*bytes_per_slot,
+        allocated_counter_bytes:allocated_slots*bytes_per_slot }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    #[test]
+    fn stripe_updates_survive_thread_exit_and_preserve_components() {
+        let mut budget=crate::resource_probe::DaemonResourceBudget::from_snapshot(Default::default());
+        budget.snapshot.logical_cpus=Some(8);budget.maximum_connections=8;configure(budget);
+        let component=super::super::COMPONENT_OTHER;let stage=super::super::STAGE_EMBEDDED_ENVELOPE_BUILD;
+        let before=(super::component(component,stage,true),super::component(component,stage,false));
+        let workers:Vec<_>=(0..32).map(|_|std::thread::spawn(move|| { for _ in 0..1000 {assert!(note(component,stage,17));} })).collect();
+        for worker in workers {worker.join().unwrap();}
+        let after=(super::component(component,stage,true),super::component(component,stage,false));
+        assert_eq!(after.0.wrapping_sub(before.0),32000*17);assert_eq!(after.1.wrapping_sub(before.1),32000);
+        let m=metrics();assert!(m.allocated_slots<=m.slots);assert_eq!(m.allocated_counter_bytes,m.allocated_slots*m.bytes_per_slot);
+        assert!(m.maximum_counter_bytes>=m.allocated_counter_bytes);
+        assert_eq!(snapshot()[component*STAGE_COUNT+stage],after);
+    }
+}
