    const char* counter_mode=std::getenv("TOFU_DB_STAGE_COUNTER_STRIPES");
    if (!counter_mode) throw std::runtime_error("counter control mode missing");
    bool zero_slots=metrics.find("\"slots\":0")!=std::string::npos;
    if (zero_slots != (std::string(counter_mode)=="0")) throw std::runtime_error("counter mode was not selected");
